import { test, expect } from '@playwright/test';

test.describe('Record Category Assignment via Dropdown', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully assign a category to a record using the dropdown', async ({ page }) => {
    // Locate and click the record to open details
    const recordItem = page.getByRole('button', { name: /record 1/i });
    await recordItem.click();

    // Verify record details are visible
    const recordTitle = page.getByRole('heading', { name: /record 1/i });
    await expect(recordTitle).toBeVisible();

    // Locate and click the category dropdown
    const categoryDropdown = page.getByRole('combobox', { name: /category/i });
    await expect(categoryDropdown).toBeVisible();
    await categoryDropdown.click();

    // Select a category from the dropdown options
    const electronicsOption = page.getByRole('option', { name: /electronics/i });
    await expect(electronicsOption).toBeVisible();
    await electronicsOption.click();

    // Verify the selected category is displayed
    await expect(categoryDropdown).toHaveValue('electronics');

    // Locate and click the save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/category assigned successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the category is updated in the record details
    const categoryDisplay = page.getByText(/category: electronics/i);
    await expect(categoryDisplay).toBeVisible();
  });

  test('should handle category assignment with validation when no category is selected', async ({ page }) => {
    // Locate and click the record to open details
    const recordItem = page.getByRole('button', { name: /record 2/i });
    await recordItem.click();

    // Verify record details are visible
    const recordTitle = page.getByRole('heading', { name: /record 2/i });
    await expect(recordTitle).toBeVisible();

    // Locate and click the category dropdown
    const categoryDropdown = page.getByRole('combobox', { name: /category/i });
    await categoryDropdown.click();

    // Verify all options are visible
    const allOptions = page.getByRole('option');
    await expect(allOptions).toHaveCount(4);

    // Click save without selecting a category
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify validation error message appears
    const errorMessage = page.getByText(/please select a category/i);
    await expect(errorMessage).toBeVisible();

    // Verify the category dropdown still shows the default placeholder
    await expect(categoryDropdown).toHaveValue('');

    // Verify the record category was not updated
    const categoryDisplay = page.getByText(/category:/i);
    await expect(categoryDisplay).toBeVisible();
  });
});
